SELECT COUNT(DISTINCT user_seq)
FROM llm_usage
WHERE created_at >= #{from} AND created_at < #{toExclusive}

SELECT user_seq AS userSeq, model_name AS modelName, COUNT(*) AS callCount, SUM(input_tokens) AS inputTokens, SUM(output_tokens) AS outputTokens FROM llm_usage WHERE created_at >= #{from} AND created_at < #{toExclusive} AND user_seq IN
#{seq}
GROUP BY user_seq, model_name
